import{_ as o,C as i,o as a,c as r,a0 as n,b as l,w as t,a as h,E as d,a1 as p}from"./chunks/framework.6sfUeJuU.js";const v=JSON.parse('{"title":"Chapter 06: In-Memory Store","description":"","frontmatter":{},"headers":[],"relativePath":"middle/06-memory-store.md","filePath":"middle/06-memory-store.md"}'),c={name:"middle/06-memory-store.md"};function g(k,e,u,m,y,b){const s=i("Mermaid");return a(),r("div",null,[e[1]||(e[1]=n('<h1 id="chapter-06-in-memory-store" tabindex="-1">Chapter 06: In-Memory Store <a class="header-anchor" href="#chapter-06-in-memory-store" aria-label="Permalink to &quot;Chapter 06: In-Memory Store&quot;">​</a></h1><h2 id="_1-the-map-hash-table" tabindex="-1">1 The Map (Hash Table) <a class="header-anchor" href="#_1-the-map-hash-table" aria-label="Permalink to &quot;1 The Map (Hash Table)&quot;">​</a></h2><p>We need a way to find a Book by its ID instantly. In Computer Science, this is a <strong>Hash Map</strong> (or Dictionary).</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> storage </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Book</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="anatomy-of-the-declaration" tabindex="-1">Anatomy of the Declaration <a class="header-anchor" href="#anatomy-of-the-declaration" aria-label="Permalink to &quot;Anatomy of the Declaration&quot;">​</a></h3><ol><li><strong><code>var</code></strong>: Create a variable.</li><li><strong><code>make</code></strong>: <strong>Crucial Keyword</strong>. Maps must be initialized before use. <ul><li>If you just did <code>var m map[string]int</code>, it is <code>nil</code>. Writing to it causes a <strong>Panic</strong> (Crash).</li><li><code>make</code> allocates the memory bucket for the map.</li></ul></li><li><strong><code>map</code></strong>: The type.</li><li><strong><code>[string]</code></strong>: The Key Type (The ID is a string).</li><li><strong><code>Book</code></strong>: The Value Type (The full Book struct).</li></ol><h2 id="_2-pointers-vs-values-book-vs-book" tabindex="-1">2 Pointers vs Values (<code>*Book</code> vs <code>Book</code>) <a class="header-anchor" href="#_2-pointers-vs-values-book-vs-book" aria-label="Permalink to &quot;2 Pointers vs Values (`*Book` vs `Book`)&quot;">​</a></h2><p>This is the hardest concept for beginners coming from Python/JS.</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GetBook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Book</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Returns a Pointer (Address)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GetBook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Book</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // Returns a Value (Photocopy)</span></span></code></pre></div><h3 id="the-metaphor" tabindex="-1">The Metaphor <a class="header-anchor" href="#the-metaphor" aria-label="Permalink to &quot;The Metaphor&quot;">​</a></h3><ul><li><strong>Value (<code>Book</code>)</strong>: You ask for the Mona Lisa. I take a <strong>Photocopy</strong> and hand it to you. If you draw a mustache on the copy, the real Mona Lisa is unchanged.</li><li><strong>Pointer (<code>*Book</code>)</strong>: You ask for the Mona Lisa. I write <strong>&quot;Room 303, Wall 2&quot;</strong> on a card and hand it to you. If you go there and draw a mustache, the real painting is changed forever.</li></ul><h3 id="why-use-pointers" tabindex="-1">Why use Pointers? <a class="header-anchor" href="#why-use-pointers" aria-label="Permalink to &quot;Why use Pointers?&quot;">​</a></h3><ol><li><strong>Performance</strong>: Copying a huge book is slow. Passing a small address card is fast.</li><li><strong>Mutability</strong>: We <em>want</em> to modify the original (e.g., updating the price).</li></ol><h3 id="comparison-memory" tabindex="-1">Comparison: Memory <a class="header-anchor" href="#comparison-memory" aria-label="Permalink to &quot;Comparison: Memory&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Language</th><th style="text-align:left;">Default Behavior</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Python</strong></td><td style="text-align:left;">Everything is a Reference (Pointer-like).</td></tr><tr><td style="text-align:left;"><strong>Java</strong></td><td style="text-align:left;">Objects are References. Primitives (<code>int</code>) are Values.</td></tr><tr><td style="text-align:left;"><strong>Go</strong></td><td style="text-align:left;">Everything is a <strong>Value</strong> (Copy) by default. You must explicitly ask for a Pointer (<code>*</code>).</td></tr></tbody></table><details class="details custom-block"><summary>🎓 Knowledge Check: If I pass a <code>Book</code> (not <code>*Book</code>) to a function and change its title, what happens to the original book?</summary><p><strong>Answer</strong>: Nothing! You only changed the <strong>photocopy</strong>. The original book remains untouched. To change the original, you must pass a <strong>Pointer</strong> (<code>*Book</code>).</p></details><h2 id="_4-the-visual-signal-the-whiteboard" tabindex="-1">4 The Visual Signal (The Whiteboard) <a class="header-anchor" href="#_4-the-visual-signal-the-whiteboard" aria-label="Permalink to &quot;4 The Visual Signal (The Whiteboard)&quot;">​</a></h2><p><strong>Concept</strong>: In-Memory Storage. <strong>Signal</strong>: A Classroom Whiteboard. Very fast to write on, everyone can see it, but if the janitor (Restart) comes, everything is erased.</p>',18)),(a(),l(p,null,{default:t(()=>[d(s,{id:"mermaid-141",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20User%20--%3E%20%7CWrite%7C%20Board%5B%22%F0%9F%93%9D%20Whiteboard%20(RAM)%22%5D%0A%20%20%20%20Restart%5B%22%E2%9A%A1%20Power%20Outage%22%5D%20--%3E%20%7CWipes%7C%20Board%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1}))])}const E=o(c,[["render",g]]);export{v as __pageData,E as default};
